/**
 * Place the server-rendered import card alongside Moodle's grading actions.
 *
 * @module local_turnitinrubricimporter/grading_actions
 * @copyright 2026 University of East London
 * @license http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Move the existing link once; leave the visible fallback if no target exists.
 */
export const init = () => {
    const fallback = document.getElementById('local-turnitinrubricimporter-actions');
    if (!fallback) {
        return;
    }
    const main = fallback.closest('[role="main"]');
    if (!main) {
        return;
    }
    const card = fallback.querySelector('a.action');
    const actions = main.querySelector('.actions:not(#local-turnitinrubricimporter-actions)');
    if (!card || !actions || card.contains(document.activeElement)) {
        return;
    }
    actions.append(card);
    fallback.remove();
};
